 "content": "def transform(grid):
    """Connect matching columns of the same-colored bars across the 2 divider."""
    g = [row[:] for row in grid]
    divider = next((r for r, row in enumerate(g) if row and all(v == 2 for v in row)), None)
    if divider is None:
        return g
    top = g[0]
    bottom = g[-1]
    colors = set(top) & set(bottom) - {0, 2}
    for color in colors:
        cols = [c for c in range(len(top)) if top[c] == color and bottom[c] == color]
        for c in cols:
            for r in range(1, divider):
                if g[r][c] == 0:
                    g[r][c] = 4
    return g
